// Symbol Table (ST) Entry - Resolution Source
typedef struct {
    unsigned int name_idx;   // Index to symbol name string
    unsigned char type_bind; // STB_GLOBAL, STB_LOCAL, STT_FUNC, STT_OBJECT
    short section_idx;       // SHN_UNDEF (Unresolved), SHN_COMMON, or section #
    uintptr_t value;         // Final resolved address/offset
} SymTableEntry;

// Relocation Table (RT) Entry - Address Patching
typedef struct {
    uintptr_t offset;    // Location in the object file to be patched
    unsigned int info;   // Defines symbol index (who needs resolving)
                         // and relocation type (e.g., R_X86_64_PC32)
    long addend;         // Constant offset/displacement

    // Loader calculates: PatchValue = Symbol.value + addend + TypeSpecificAdjustment
} RelocEntry;
